import{at as e,it as t,n,vt as r}from"./chunks/framework.D9OOHiq-.js";var i=JSON.parse(`{"title":"Flow & Triggers","description":"","frontmatter":{},"headers":[],"relativePath":"en/modules/dungeon/flow.md","filePath":"en/modules/dungeon/flow.md","lastUpdated":0}`),a={name:`en/modules/dungeon/flow.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="flow-triggers" tabindex="-1">Flow &amp; Triggers <a class="header-anchor" href="#flow-triggers" aria-label="Permalink to “Flow &amp; Triggers”">​</a></h1><p><code>flow.yml</code> is the dungeon&#39;s gameplay blueprint: how rooms advance, how many waves spawn, when gates open, and which path players take after a choice. It lives at <code>plugins/EmakiDungeon/world/&lt;dungeonId&gt;/flow.yml</code> and is generated from the bundled template when missing. Module IDs must be unique inside a dungeon; duplicates and out-of-bounds definitions are validated at load time, and a failing load falls back to an empty flow for that instance — run <code>/edg admin validate</code> to health-check all templates up front</p><p>Most people never hand-write it: place markers with the <a href="./commands.html#editor-session-commands">map editor</a> in game and save to have them written into <code>flow.yml</code>. The generated structure and how to wire modules together with conditions and actions are explained below</p><h2 id="file-skeleton" tabindex="-1">File skeleton <a class="header-anchor" href="#file-skeleton" aria-label="Permalink to “File skeleton”">​</a></h2><p>The bundled template looks like this (excerpt from the real file):</p><div class="language-yaml" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">version</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;1.0.0&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">rooms</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {}</span></span></code></pre></div><p><strong>Entry-point convention</strong>: never write a <code>spawn_point</code> override section in a new dungeon&#39;s flow.yml (the bundled default template no longer ships it). The entry point falls back to the world spawn: set the template world spawn to a clear landing spot with <code>/setworldspawn</code> and make sure the spawn stored in the template <code>level.dat</code> is valid (the server validates the stored spawn on world load and may re-pick a different position otherwise). After exporting the template, verify flow has no such section, then confirm the actual landing with one real entry. Region-based modules that depend on the entry position (such as <code>entry_timer</code>&#39;s <code>region</code>) must cover the real landing spot. <code>spawn_point</code> remains available as an explicit override — once written, entry, respawn and settlement all use it</p><p>Every module follows a two-level shape: &quot;section name -&gt; { module id -&gt; module body }&quot;, and the body carries its own <code>id</code> and <code>enabled</code> switch. Here is a room timer from a tested dungeon:</p><div class="language-yaml" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">room_timers</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">  entry_timer</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">    id</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">entry_timer</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">    enabled</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">    region</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">      min</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">        x</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">-20.0</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">        y</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">55.0</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">        z</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">-20.0</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">      max</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">        x</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">20.0</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">        y</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">80.0</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">        z</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">20.0</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">    seconds</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">15</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">    on_zero</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">      type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">complete</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">      cause</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">timed</span></span></code></pre></div><p>What this entry means: once players enter the region a 15-second countdown starts, and on zero the <code>complete</code> action ends the run. Regions (<code>region</code>) are always two corner coordinates, <code>min</code> and <code>max</code></p><h2 id="module-catalog-22-types" tabindex="-1">Module catalog (22 types) <a class="header-anchor" href="#module-catalog-22-types" aria-label="Permalink to “Module catalog (22 types)”">​</a></h2><table tabindex="0"><thead><tr><th>Section</th><th>Purpose</th><th>Key content</th></tr></thead><tbody><tr><td><code>spawn_point</code></td><td>Entry location of the run</td><td><code>location</code> (<code>x</code> / <code>y</code> / <code>z</code> / <code>yaw</code>)</td></tr><tr><td><code>rooms</code></td><td>Room topology (list)</td><td><code>id</code>, <code>order</code>, <code>region</code>, <code>arrival</code> point</td></tr><tr><td><code>checkpoints</code></td><td>Checkpoints</td><td><code>region</code>, point, <code>min_players</code>, <code>record_id</code></td></tr><tr><td><code>respawn_points</code></td><td>Respawn points</td><td>point, linked <code>checkpoint</code></td></tr><tr><td><code>exit_points</code></td><td>Exits</td><td>point, <code>need_confirm</code> requires a second confirmation</td></tr><tr><td><code>gates</code></td><td>Gates</td><td><code>door_regions</code> blocks, <code>conditions</code>, <code>logic</code> (<code>AND</code>/<code>OR</code>), <code>open_mode</code>, <code>redstone</code> point</td></tr><tr><td><code>spawn_points</code></td><td>Spawn points</td><td><code>spawn_id</code>, point, <code>range</code>, <code>min_players</code>, <code>once</code>, <code>waves</code> list</td></tr><tr><td><code>trigger_zones</code></td><td>Trigger zones</td><td><code>region</code>, <code>direction</code> (<code>enter</code>/<code>leave</code>), <code>conditions</code></td></tr><tr><td><code>block_interactions</code></td><td>Block interactions</td><td>point, <code>click</code>, <code>conditions</code>, <code>actions</code></td></tr><tr><td><code>rewards</code></td><td>Reward points</td><td>point, <code>loot_table</code> id, <code>conditions</code></td></tr><tr><td><code>boss_points</code></td><td>Boss points</td><td>point, <code>source</code>, <code>boss_id</code>, <code>conditions</code></td></tr><tr><td><code>options</code></td><td>Branch options</td><td><code>option_id</code>, <code>select_mode</code> (<code>single</code>/<code>multi</code>), <code>cases</code>, <code>time_limit_seconds</code>, <code>min_select</code>/<code>max_select</code>, <code>safe_point</code>, <code>ending_map</code></td></tr><tr><td><code>hints</code></td><td>Hint points</td><td>point + <code>region</code>, <code>text</code>, <code>channel</code>, <code>conditions</code></td></tr><tr><td><code>teleport_zones</code></td><td>Teleport zones</td><td><code>region</code> -&gt; <code>target</code>, <code>all_members</code></td></tr><tr><td><code>boundary_zones</code></td><td>Boundary zones</td><td><code>region</code> + <code>pullback</code> point</td></tr><tr><td><code>effect_zones</code></td><td>Effect zones</td><td><code>region</code>, <code>effects</code>, <code>interval_ticks</code></td></tr><tr><td><code>mechanisms</code></td><td>Mechanisms</td><td><code>targets</code> block-state list (<code>block_data</code> + point), <code>conditions</code></td></tr><tr><td><code>room_timers</code></td><td>Room timers</td><td><code>region</code>, <code>seconds</code>, <code>on_zero</code> action</td></tr><tr><td><code>kill_targets</code></td><td>Kill targets</td><td><code>target</code>, <code>count</code>, <code>scope</code> region, <code>actions</code></td></tr><tr><td><code>item_interactions</code></td><td>Item interactions</td><td>point, <code>item</code>, <code>amount</code>, <code>consume</code>, <code>conditions</code>, <code>actions</code></td></tr><tr><td><code>fx_points</code></td><td>FX points</td><td>point + <code>region</code>, <code>sound</code>, <code>particle</code>, <code>radius</code>, <code>conditions</code></td></tr><tr><td><code>temp_items</code></td><td>Temporary items</td><td><code>item</code>, <code>amount</code>, <code>timing</code>, <code>hint</code>; taken back when the instance ends</td></tr></tbody></table><p>Each wave inside a spawn point&#39;s <code>waves</code> carries <code>interval_ticks</code> (spacing), <code>drop_loot</code> (whether the wave drops loot), and <code>mobs</code> entries (<code>id</code> / <code>count</code> / <code>weight</code>); mob ids accept vanilla entity ids and the <code>emakimobs:</code> prefix (requires EmakiMobs)</p><h2 id="conditions" tabindex="-1">Conditions <a class="header-anchor" href="#conditions" aria-label="Permalink to “Conditions”">​</a></h2><p>A module&#39;s <code>conditions</code> is a list where each entry is judged by its <code>type</code> with <code>params</code> flattened alongside, and you can nest entries with <code>logic</code> (<code>AND</code>/<code>OR</code>) plus <code>children</code>. <strong>An unknown condition type always evaluates to false:</strong></p><table tabindex="0"><thead><tr><th>Type</th><th>Judges</th><th>Common params</th></tr></thead><tbody><tr><td><code>range</code></td><td>Enough targets inside range</td><td><code>min_players</code>, <code>target</code> (<code>player</code>/<code>mob</code>)</td></tr><tr><td><code>region</code></td><td>Entered or left a region</td><td><code>direction</code> (<code>enter</code>/<code>leave</code>)</td></tr><tr><td><code>block_interact</code></td><td>Block interaction click matches</td><td><code>click</code></td></tr><tr><td><code>block_activate</code></td><td>Block activated (button, lever, ...)</td><td>—</td></tr><tr><td><code>redstone</code></td><td>Redstone level matches; <code>change</code> means &quot;changed&quot;</td><td><code>level</code></td></tr><tr><td><code>clear</code></td><td>The waves of a spawn point are cleared</td><td><code>spawn</code></td></tr><tr><td><code>boss_kill</code></td><td>The specified boss is dead</td><td><code>boss_id</code></td></tr><tr><td><code>kill_count</code></td><td>Kill count reached</td><td><code>target</code>, <code>count</code></td></tr><tr><td><code>timer</code></td><td>The specified timer module fired</td><td><code>module</code></td></tr><tr><td><code>item</code></td><td>An item interaction happened</td><td>—</td></tr><tr><td><code>command</code></td><td>Command result matches</td><td><code>expected</code></td></tr><tr><td><code>player_state</code></td><td>Player state matches (optionally with remaining lives)</td><td><code>state</code>, <code>remaining_lives</code></td></tr><tr><td><code>script</code></td><td>Verdict written by the dungeon script</td><td>—</td></tr></tbody></table><h2 id="actions" tabindex="-1">Actions <a class="header-anchor" href="#actions" aria-label="Permalink to “Actions”">​</a></h2><p>Once conditions hold, the listed actions run the same way (<code>type</code> plus sibling params); timers hang theirs on <code>on_zero</code>:</p><table tabindex="0"><thead><tr><th>Type</th><th>Effect</th><th>Common params</th></tr></thead><tbody><tr><td><code>hint</code></td><td>Push a hint to the player</td><td><code>text</code>, <code>channel</code></td></tr><tr><td><code>message</code></td><td>Send a message by lang key</td><td><code>key</code>, <code>channel</code></td></tr><tr><td><code>command</code></td><td>Run a console command (player placeholder supported)</td><td><code>command</code></td></tr><tr><td><code>teleport</code></td><td>Teleport the player</td><td>coordinates</td></tr><tr><td><code>fx</code></td><td>Play effects</td><td>sound / particle related</td></tr><tr><td><code>set_block</code></td><td>Change a block state</td><td><code>block_data</code> + point</td></tr><tr><td><code>open_gate</code></td><td>Open a gate</td><td>gate id</td></tr><tr><td><code>spawn_wave</code></td><td>Start a spawn point&#39;s wave</td><td>spawn point id</td></tr><tr><td><code>fail</code></td><td>Fail the run</td><td><code>cause</code></td></tr><tr><td><code>complete</code></td><td>Clear the run</td><td><code>cause</code></td></tr><tr><td><code>give_temp_item</code></td><td>Grant a temporary item (removed at instance end)</td><td>item and amount</td></tr></tbody></table><p>Dungeon-level lifecycle actions (<code>dungeon_enter</code> and friends, 11 segments) are not written in flow; they live in the main configuration&#39;s <code>action</code> section — see <a href="./configuration.html">Configuration</a></p><h2 id="branch-options-and-endings" tabindex="-1">Branch options and endings <a class="header-anchor" href="#branch-options-and-endings" aria-label="Permalink to “Branch options and endings”">​</a></h2><p>The <code>options</code> section defines the forks in front of the players, and the whole interaction happens in chat:</p><ol><li>A prompt appears: &quot;choose: ... (enter a number or id)&quot;</li><li>Then a second confirmation: &quot;chosen ... type <code>confirm</code> to lock it in (times out to auto-lock), type <code>cancel</code> to abort&quot;</li><li>The count must fall within <code>min_select</code>~<code>max_select</code>; <code>single</code> for single choice, <code>multi</code> for multiple</li><li><code>time_limit_seconds</code> is the selection timer, <code>0</code> means none; timing out counts as no choice</li></ol><p>Each candidate (<code>cases</code>) carries its <code>label</code>, its <code>ending</code> id, and <code>seal_regions</code> <strong>seal areas</strong>: losing paths get sealed and players approaching a sealed area are pulled back to that candidate&#39;s <code>safe_point</code>. Candidates combine through <code>ending_map</code> into the final <code>ending</code>. Firing order: <code>DungeonChoiceEvent</code> before the prompt is even shown (cancellable - cancel and no prompt appears), <code>DungeonOptionConfirmEvent</code> when locked in, <code>DungeonSealPathEvent</code> when a path seals, and <code>DungeonEndingEvent</code> at the ending (full list on <a href="./api.html">API</a>)</p><h2 id="map-editor" tabindex="-1">Map editor <a class="header-anchor" href="#map-editor" aria-label="Permalink to “Map editor”">​</a></h2><p>Run <code>/edg editor &lt;dungeonId&gt;</code> (needs <code>emakidungeon.editor</code>) to enter the dedicated edit world; then:</p><ol><li><strong>Markers</strong>: single-point markers (<code>spawn</code>/<code>option</code>/<code>chest</code>) go on the aimed block, region markers (<code>room</code>/<code>gate</code>/<code>trigger</code>) use <code>pos1</code> + <code>pos2</code>; <code>marks</code> lists what is staged</li><li><strong>Panels</strong>: the main panel has four areas - dungeon metadata, spawn points and waves, gates, and branch options; field edits are staged first</li><li><strong>Terrain</strong>: <code>fill &lt;block&gt;</code> fills the circled area frame by frame</li><li><strong>Test</strong>: <code>test</code> runs a normal entry from the saved template, <strong>counts nothing and never ranks</strong>; refused while unsaved changes exist</li><li><strong>Save</strong>: &quot;Save and write back&quot; persists markers and panel edits into <code>config.yml</code> / <code>flow.yml</code> plus terrain, echoing a new generation number; <code>exit</code> quits and discards unsaved changes</li></ol><p>Only one editing session per template at a time; you cannot open the editor while inside an instance or a challenge flow - finish those first; leftover edit worlds are swept on plugin startup</p><h2 id="graaljs-dungeon-scripts" tabindex="-1">GraalJS dungeon scripts <a class="header-anchor" href="#graaljs-dungeon-scripts" aria-label="Permalink to “GraalJS dungeon scripts”">​</a></h2><p><code>scripts/&lt;dungeonId&gt;.js</code> is loaded with every instance of that dungeon and released when the instance is destroyed (switch and timeout live in the global <code>script</code> section). In a script you can:</p><ul><li><code>dungeon.takeover()</code> take over pacing of the whole run</li><li><code>onTrigger(&#39;onEnter&#39;, ...)</code> / <code>waitFor(&#39;onRoomEnter&#39;)</code> subscribe and await triggers (such as <code>onEnter</code>, <code>onRoomEnter</code>, <code>onWaveClear</code>, <code>onRoomClear</code>, <code>onBossKill</code>, <code>onGateOpen</code>)</li><li><code>dungeon.spawnWave(...)</code> / <code>dungeon.openGate(...)</code> / <code>dungeon.enterRoom(...)</code> / <code>dungeon.complete(...)</code> drive the flow</li><li><code>dungeon.registerEntry(...)</code> register temporary entries for everyone (removed when the run ends), <code>dungeon.hint(...)</code> push hints</li><li><code>dungeon.factFlag(...)</code> / <code>dungeon.setFact(...)</code> pass state between script facts</li></ul><p>A script error or timeout only <strong>disables that script</strong> while the instance keeps running (unless you turn on <code>script.fail-on-error</code>); a complete example ships as <code>examples/example_flow.js</code> in the plugin resources. Third-party plugins can register script triggers through the API — see <a href="./api.html">API</a></p>`,32)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};